CREATE TABLE IF NOT EXISTS customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), lead_id UUID REFERENCES leads(id), booking_id UUID UNIQUE REFERENCES bookings(id), customer_number VARCHAR(40) UNIQUE NOT NULL, full_name VARCHAR(160) NOT NULL, mobile VARCHAR(20) NOT NULL, email VARCHAR(180), status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, document_type VARCHAR(60) NOT NULL, file_name VARCHAR(220), storage_key VARCHAR(300), version_no INT NOT NULL DEFAULT 1, verification_status VARCHAR(30) NOT NULL DEFAULT 'PENDING', rejection_reason VARCHAR(500), masked BOOLEAN NOT NULL DEFAULT TRUE, expiry_date DATE, uploaded_by UUID REFERENCES users(id), verified_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS loan_applications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, status VARCHAR(30) NOT NULL DEFAULT 'NOT_APPLIED', bank_name VARCHAR(160), loan_amount NUMERIC(15,2), emi NUMERIC(15,2), sanction_date DATE, loan_officer VARCHAR(160), sanction_document_id UUID REFERENCES customer_documents(id), rejection_reason VARCHAR(500), disbursement_date DATE, updated_by UUID REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agreements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, agreement_date DATE, agreement_value NUMERIC(15,2), stamp_duty NUMERIC(15,2), registration_date DATE, registration_number VARCHAR(80), legal_notes VARCHAR(1500), agreement_document_id UUID REFERENCES customer_documents(id), status VARCHAR(30) NOT NULL DEFAULT 'PENDING', updated_by UUID REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS possession_cases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID UNIQUE NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, status VARCHAR(30) NOT NULL DEFAULT 'NOT_READY', scheduled_date DATE, possession_letter_document_id UUID REFERENCES customer_documents(id), signoff_name VARCHAR(160), signoff_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by UUID REFERENCES users(id), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS possession_checklist_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), possession_id UUID NOT NULL REFERENCES possession_cases(id) ON DELETE CASCADE, item_code VARCHAR(50) NOT NULL, item_name VARCHAR(160) NOT NULL, completed BOOLEAN NOT NULL DEFAULT FALSE, completed_at TIMESTAMPTZ, completed_by UUID REFERENCES users(id), remarks VARCHAR(500), UNIQUE(possession_id,item_code));
CREATE INDEX IF NOT EXISTS idx_customer_documents_booking ON customer_documents(booking_id,verification_status);
CREATE INDEX IF NOT EXISTS idx_possession_items_case ON possession_checklist_items(possession_id,completed);
